        }
        x = v;
        while (d > 0) {
            emon.Port.CellsPush(et, 48 + (x / d));
            x -= (x / d) * d;
            d = d / 10;
        }
        return 0;
    }
    public static int LsWrapBegin(emon.Port.Cells et, int opener, int code, int value) {
        // Start a new text run at the end of `et`: the group's opener, its header cell (`ls-s-base` + code), the
        // value's digits when it is not negative, and the separator. Answers the run's start; the caller then
        // pushes the marker's text, `ls-wrap-end`, and what follows, and `ls-wrap-set` points the word at the run.
        int s = emon.Port.CellsLen(et);
        emon.Port.CellsPush(et, opener);
        emon.Port.CellsPush(et, LsSBase() + code);
        if (value >= 0) {
            LsPushNum(et, value);
        }
        emon.Port.CellsPush(et, LsSSep());
        return s;
    }
    public static int LsWrapEnd(emon.Port.Cells et) {
        emon.Port.CellsPush(et, LsSEnd());
        return 0;
    }
    public static int LsWrapSet(emon.Port.Cells wd, emon.Port.Cells et, int w, int start) {
        // Point word w at the run that begins at `start` and ends at the end of `et`.
        Evidence.WdSet(wd, w, Evidence.HdTstart(), start);
        Evidence.WdSet(wd, w, Evidence.HdTlen(), emon.Port.CellsLen(et) - start);
        return 0;
    }
    public static int LsCopyWord(emon.Port.Cells et, emon.Port.Cells wd, int w, int from) {
        // Append the code points of word w's current text from index `from` to `et`.
        int ts = Evidence.WdGet(wd, w, Evidence.HdTstart());
        int tl = Evidence.WdGet(wd, w, Evidence.HdTlen());
        int j = from;
        while (j < tl) {
            emon.Port.CellsPush(et, emon.Port.CellsAt(et, ts + j));
            j += 1;
        }
        return 0;
    }
    internal static int LsWrapItem(emon.Port.Cells wd, emon.Port.Cells et, int w, int scheme, int value, int mlen, int bullet) {
        // Make word w start with an item group. A TEXT marker (`bullet` -1): the group holds the word's first `mlen`
        // code points. A SHAPE (`bullet` the character the shape is): the group holds that character and the word is
        // kept whole after it.
        int s = LsWrapBegin(et, LsSItem(), scheme, value);
        if (bullet < 0) {
            int j = 0;
            int ts = Evidence.WdGet(wd, w, Evidence.HdTstart());
            while (j < mlen) {
                emon.Port.CellsPush(et, emon.Port.CellsAt(et, ts + j));
                j += 1;
            }
            LsWrapEnd(et);
            LsCopyWord(et, wd, w, mlen);
        } else {
            emon.Port.CellsPush(et, bullet);
            LsWrapEnd(et);
            LsCopyWord(et, wd, w, 0);
        }
        LsWrapSet(wd, et, w, s);
        return 0;
    }
    public static bool LsUpright(emon.Port.Cells ln, int l) {
        // An upright line a table does not hold (P5: a table's lines are claimed and its cells are written from them: a
        // group in one would be in the cell's text). Every stage of this module and of `emon.notes` asks this, and only this,
        // of a line before it looks at it.
        int r = Evidence.LnGet(ln, l, Evidence.LhRot());
        if (Table.TbClaimed(ln, l) != 0) {
            return 0 == 1;
        }
        return (r < 100) || (r > 35900);
    }
    public static int LsLineSize(emon.Port.Cells sf, emon.Port.Cells ln, int l) {
        // The size the line's text is set in (centipoints): the style inventory's, else its height over 5/4.
        int s = Style.StGet(sf, l, Style.SfkSize());
        if (s > 0) {
            return LsCap(s);
        }
        return LsCap((LsCap(Evidence.LnGet(ln, l, Evidence.LhY1()) - Evidence.LnGet(ln, l, Evidence.LhY0())) * 4) / 5);
    }
    internal static int LsPages(emon.Port.Cells ln, emon.Port.Cells pi) {
        // `pi`: for page p (1-based) the first line of the page plus one and one past its last, cells 2p and 2p+1; the
        // lines of a page are consecutive in `ln` (the text layer writes them page by page). Answers 1, or 0 when they
        // are not (a stage that reordered the lines): then no shape is associated.
        int n = Evidence.LnCount(ln);
        int l = 0;
        int last = 0;
        int mx = 0;
        emon.Port.CellsDrop(pi, 0);
        while (l < n) {
            int p = Evidence.LnGet(ln, l, Evidence.LhPage());
            if (p < last) {
                return 0;
            }
            if (p > 100000) {
                return 0;
            }
            last = p;
            if (p > mx) {
                mx = p;
            }
            l += 1;
        }
        l = 0;
        while (l < (2 * (mx + 2))) {
            emon.Port.CellsPush(pi, 0);
            l += 1;
        }
        l = 0;
        while (l < n) {
            int p = Evidence.LnGet(ln, l, Evidence.LhPage());
            if (emon.Port.CellsAt(pi, 2 * p) == 0) {
                emon.Port.CellsSet(pi, 2 * p, l + 1);
            }
            emon.Port.CellsSet(pi, (2 * p) + 1, l + 1);
            l += 1;
        }
        return 1;
    }
    internal static int LsAttach(emon.Port.Cells ln, emon.Port.Cells sf, emon.Port.Cells hc, int l, int r, int x0, int x1, int w, int cy0) {
        // Associate shape r (its right edge x1, its width w, its centre cy) with line l if the shape stands where a
        // bullet stands: a fraction of an em to the left of the first word, on the x-height, of a fraction of an em in
        // size. The line keeps the nearest one. Answers 1 when this was the first shape the line got.
        int cy = LsCap(cy0);
        int sz = LsLineSize(sf, ln, l);
        int lx = LsCap(Evidence.LnGet(ln, l, Evidence.LhX0()));
        int by = LsCap(Evidence.LnGet(ln, l, Evidence.LhBy0()));
        int gap = LsCap(lx - LsCap(x1));
        int rx = LsCap(Evidence.LnGet(ln, l, Evidence.LhX1()));
        int gap2 = LsCap(LsCap(x0) - rx);
        if (((w * 100) >= (sz * 12)) && ((w * 100) <= (sz * 70)) && ((cy * 100) >= ((by * 100) - (sz * 80))) && ((cy * 10) <= ((by * 10) - sz))) {
            // to the left of the line's start (a bullet), or to the right of its end (the bullet of a line that runs right to left)
            if (((gap * 16) >= sz) && ((gap * 10) <= (sz * 25))) {
                int old = LsGet(hc, l, LsKShape());
                if ((old == 0) || (LsGet(hc, l, LsKRtl()) == 1) || (gap < LsGet(hc, l, LsKGap()))) {
                    LsPut(hc, l, LsKShape(), r + 1);
                    LsPut(hc, l, LsKGap(), gap);
                    LsPut(hc, l, LsKRtl(), 0);
                    if (old == 0) {
                        return 1;
                    }
                }
            }
            if (((gap2 * 16) >= sz) && ((gap2 * 10) <= (sz * 25))) {
                int old = LsGet(hc, l, LsKShape());
                if ((old == 0) || ((LsGet(hc, l, LsKRtl()) == 1) && (gap2 < LsGet(hc, l, LsKGap())))) {
                    LsPut(hc, l, LsKShape(), r + 1);
                    LsPut(hc, l, LsKGap(), gap2);
                    LsPut(hc, l, LsKRtl(), 1);
                    if (old == 0) {
                        return 1;
                    }
                }
            }
        }
        return 0;
    }
    internal static int LsShapes(emon.Port.Cells ln, emon.Port.Cells sf, emon.Port.Cells pa, emon.Port.Cells pi, emon.Port.Cells hc) {
        // Associate every small filled or stroked circle or square with the line it precedes (see the module's head):
        // the line's row gets 1 + the path's row and the gap. Answers how many lines got one.
        int np = Evidence.PaCount(pa);
        int r = 0;
        int got = 0;
        int seen = 0;
        int l = 0;
        while ((r < np) && (seen < LsMaxshape)) {
            int fl = Evidence.PaGet(pa, r, Evidence.PfFlags());
            int x0 = Evidence.PaGet(pa, r, Evidence.PfX0());
            int y0 = Evidence.PaGet(pa, r, Evidence.PfY0());
            int x1 = Evidence.PaGet(pa, r, Evidence.PfX1());
            int y1 = Evidence.PaGet(pa, r, Evidence.PfY1());
            int w = x1 - x0;
            int h = y1 - y0;
            int p = Evidence.PaGet(pa, r, Evidence.PfPage());
            // D1630: a bullet is a disc (a curve) or a square (a rectangle); a filled polygon (an arrow head, a triangle) is no bullet
            if (((fl & 4) == 0) && ((Evidence.PaGet(pa, r, Evidence.PfKind()) == Evidence.PaCurve()) || (Evidence.PaGet(pa, r, Evidence.PfKind()) == Evidence.PaRect())) && ((fl & 24) != 0) && (w > 0) && (h > 0) && (w < 1500) && (h < 1500) && (p >= 1) && (((2 * p) + 1) < emon.Port.CellsLen(pi)) && ((4 * LsAbs(w - h)) <= LsMax(w, h))) {
                seen += 1;
                l = emon.Port.CellsAt(pi, 2 * p) - 1;
                while ((l >= 0) && (l < emon.Port.CellsAt(pi, (2 * p) + 1))) {
                    if (LsUpright(ln, l)) {
                        got += LsAttach(ln, sf, hc, l, r, x0, x1, w, (y0 + y1) / 2);
                    }
                    l += 1;
                }
            }
            r += 1;
        }
        return got;
    }
    internal static int LsShapeChar(emon.Port.Cells pa, int r) {
        // The bullet a path stands for: a filled disc, a ring, a filled square, a hollow square.
        int fl = Evidence.PaGet(pa, r, Evidence.PfFlags());
        int k = Evidence.PaGet(pa, r, Evidence.PfKind());
        int filled = fl & 8;
        if (k == Evidence.PaCurve()) {
            if (filled != 0) {
                return 8226;
            }
            return 9702;
        }
        if (filled != 0) {
            return 9642;
        }
        return 9643;
    }
    public static int LsFirstWord(emon.Port.Cells wd, emon.Port.Cells ln, int l) {
        // The first word of the line that has text; -1 when none.
        int w0 = Evidence.LnGet(ln, l, Evidence.LhFirst());
        int wn = Evidence.LnGet(ln, l, Evidence.LhCount());
        int i = 0;
        while (i < wn) {
            if (LsWl(wd, w0 + i) > 0) {
                return w0 + i;
            }
            i += 1;
        }
        return -1;
    }
    public static int LsSecondWord(emon.Port.Cells wd, emon.Port.Cells ln, int l) {
        int w0 = Evidence.LnGet(ln, l, Evidence.LhFirst());
        int wn = Evidence.LnGet(ln, l, Evidence.LhCount());
        int i = 0;
        int seen = 0;
        while (i < wn) {
            if (LsWl(wd, w0 + i) > 0) {
                if (seen == 1) {
                    return w0 + i;
                }
                seen += 1;
            }
            i += 1;
        }
        return -1;
    }
    internal static int LsPushCand(emon.Port.Cells cd, emon.Port.Cells ln, int l, int sch, int val, int sch2, int val2, int pun, int cls, int ch, int x, int partner) {
        // Append one candidate row of `LS_CD` cells: line, page, scheme, value, scheme2, value2, punct, x0 of the line,
        // class (1 strong bullet, 2 weak, 3 number or letter, 4 shape), the bullet character.
        emon.Port.CellsPush(cd, l);
        emon.Port.CellsPush(cd, Evidence.LnGet(ln, l, Evidence.LhPage()));
        emon.Port.CellsPush(cd, sch);
        emon.Port.CellsPush(cd, val);
        emon.Port.CellsPush(cd, sch2);
        emon.Port.CellsPush(cd, val2);
        emon.Port.CellsPush(cd, pun);
        emon.Port.CellsPush(cd, x);
        emon.Port.CellsPush(cd, cls);
        emon.Port.CellsPush(cd, ch);
        emon.Port.CellsPush(cd, partner);
        emon.Port.CellsPush(cd, 0);
        return 0;
    }
    internal static int LsMlen(emon.Port.Cells wd, emon.Port.Cells et, int w, emon.Port.Cells ws) {
        // The marker length of word w (the parser's cell 4).
        LsParse(wd, et, w, ws);
        return emon.Port.CellsAt(ws, 4);
    }
    internal static int LsTextx(emon.Port.Cells wd, emon.Port.Cells ln, emon.Port.Cells et, emon.Port.Cells hc, int l, int w, int cls, emon.Port.Cells ws) {
        // The x where the item's text starts: the word after the marker; a glued marker's share of its word; the
        // word itself for a shape. 0 when the line has nothing after the marker. (Markers are often right aligned, so
        // the marker's own x says little about the indent: the text's does.)
        if (cls == 4) {
            if (LsGet(hc, l, LsKRtl()) == 1) {
                return 10000000 - LsCap(Evidence.LnGet(ln, l, Evidence.LhX1()));
            }
            return Evidence.WdGet(wd, w, Evidence.HdX0());
        }
        int w2 = LsSecondWord(wd, ln, l);
        int wl = LsWl(wd, w);
        int ml = LsMlen(wd, et, w, ws);
        if (ml < wl) {
            return Evidence.WdGet(wd, w, Evidence.HdX0()) + (((Evidence.WdGet(wd, w, Evidence.HdX1()) - Evidence.WdGet(wd, w, Evidence.HdX0())) * ml) / wl);
        }
        if (w2 >= 0) {
            return Evidence.WdGet(wd, w2, Evidence.HdX0());
        }
        return 0;
    }
    internal static int LsRtlSide(emon.Port.Cells ln, int m, int t) {
        // 1 when the text line t lies to the LEFT of its marker line m: the item runs right to left.
        if (Evidence.LnGet(ln, t, Evidence.LhX1()) <= Evidence.LnGet(ln, m, Evidence.LhX0())) {
            return 1;
        }
        return 0;
    }
    internal static int LsTakePartner(emon.Port.Cells wd, emon.Port.Cells et, emon.Port.Cells ln, int w, int l, int m, int scheme, int value) {
        // The item whose marker stands alone on line m and whose text starts with word w: w gets the group (the marker's
        // text), the marker's word is emptied, line m is taken out of the lines (page -7, as furniture's are) and the text's
        // line grows to hold it.
        int wm = LsFirstWord(wd, ln, m);
        int s = LsWrapBegin(et, LsSItem(), scheme, value);
        int ts = Evidence.WdGet(wd, wm, Evidence.HdTstart());
        int tl = Evidence.WdGet(wd, wm, Evidence.HdTlen());
        int j = 0;
        while (j < tl) {
            emon.Port.CellsPush(et, emon.Port.CellsAt(et, ts + j));
            j += 1;
        }
        LsWrapEnd(et);
        LsCopyWord(et, wd, w, 0);
        LsWrapSet(wd, et, w, s);
        Evidence.WdSet(wd, wm, Evidence.HdTlen(), 0);
        int mx0 = Evidence.LnGet(ln, m, Evidence.LhX0());
        int mx1 = Evidence.LnGet(ln, m, Evidence.LhX1());
        int lx0 = Evidence.LnGet(ln, l, Evidence.LhX0());
        int lx1 = Evidence.LnGet(ln, l, Evidence.LhX1());
        if (LsRtlSide(ln, m, l) == 1) {
            if (mx1 > lx1) {
                Evidence.LnSet(ln, l, Evidence.LhX1(), mx1);
            }
        } else {
            if (mx0 < lx0) {
                Evidence.LnSet(ln, l, Evidence.LhX0(), mx0);
            }
        }
        Evidence.LnSet(ln, m, Evidence.LhPage(), -7);
        return 0;
    }
    internal static int LsSmall(emon.Port.Cells wd, emon.Port.Cells ln, emon.Port.Cells sf, int l) {
        // 1 when line l is set smaller than three quarters of the body's size: the labels of a figure, the cells of a table
        // in small type; a list there is not what this stage is after.
        int bsz = Style.StHget(sf, Style.SfhSize());
        if ((bsz > 0) && ((LsLineSize(sf, ln, l) * 100) < (bsz * 75))) {
            return 1;
        }
        return 0;
    }
    internal static int LsLetterAfter(emon.Port.Cells wd, emon.Port.Cells ln, emon.Port.Cells et, int l, int w) {
        // 1 when the word after the marker word w of line l starts with a letter (of any script of letters): a dash before a
        // number is a table's blank or a minus, not a bullet.
        int w2 = LsSecondWord(wd, ln, l);
        if (w2 < 0) {
            return 0;
        }
        int c = LsWc(wd, et, w2, 0);
        if ((c >= 65) && (c <= 90)) {
            return 1;
        }
        if ((c >= 97) && (c <= 122)) {
            return 1;
        }
        if ((c >= 192) && ((c <= 8191) && ((c != 215) && (c != 247)))) {
            return 1;
        }
        if (c >= 12288) {
            return 1;
        }
        return 0;
    }
    internal static int LsPartner(emon.Port.Cells wd, emon.Port.Cells ln, emon.Port.Cells sf, emon.Port.Cells hc, int l) {
        // The line that holds the TEXT of the item whose marker is alone on line l: the one sibling on its row, at the same
        // baseline, close beside it (to its right, or to its left when the text runs right to left), with text of its own
        // and nothing else. -1 when there is none. (A text layer builds two lines out of a marker and its text when
        // they are set in different fonts: a right to left list is the common case.)
        int t = Style.StGet(sf, l, Style.SfkSibline());
        if (t < 0) {
            return -1;
        }
        if (Style.StGet(sf, l, Style.SfkNsib()) != 1) {
            return -1;
        }
        if (!LsUpright(ln, t)) {
            return -1;
        }
        if ((LsGet(hc, t, LsKFlags()) != 0) || (Heading.HdLevel(hc, t) > 0)) {
            return -1;
        }
        if (Evidence.LnGet(ln, t, Evidence.LhPage()) != Evidence.LnGet(ln, l, Evidence.LhPage())) {
            return -1;
        }
        if (LsFirstWord(wd, ln, t) < 0) {
            return -1;
        }
        int sz = LsLineSize(sf, ln, l);
        int mx0 = LsCap(Evidence.LnGet(ln, l, Evidence.LhX0()));
        int mx1 = LsCap(Evidence.LnGet(ln, l, Evidence.LhX1()));
        int tx0 = LsCap(Evidence.LnGet(ln, t, Evidence.LhX0()));
        int tx1 = LsCap(Evidence.LnGet(ln, t, Evidence.LhX1()));
        int db = LsAbs(LsCap(Evidence.LnGet(ln, l, Evidence.LhBy0())) - LsCap(Evidence.LnGet(ln, t, Evidence.LhBy0())));
        if ((db * 3) > sz) {
            return -1;
        }
        if (((tx0 + (sz / 4)) >= mx1) && (((tx0 - mx1) * 10) <= (sz * 100))) {
            return t;
        }
        if (((tx1 - (sz / 4)) <= mx0) && (((mx0 - tx1) * 10) <= (sz * 100))) {
            return t;
        }
        return -1;
    }
    internal static int LsBulletBefore(emon.Port.Cells wd, emon.Port.Cells ln, emon.Port.Cells et, emon.Port.Cells sf, emon.Port.Cells hc, int l, emon.Port.Cells ws) {
        // D1630 (smoke review A issue 13): 1 when a bullet precedes line l on its own row: the line on the same baseline just to its left starts with a strong bullet (a
        // word, or a shape the line has). A bullet, a lead-in and an en dash and the text, split at the lead-in's underline, is one item, whose dash is the text's own.
        int t = Style.StGet(sf, l, Style.SfkSibline());
        if (t < 0) {
            return 0;
        }
        if (!LsUpright(ln, t)) {
            return 0;
        }
        if (Evidence.LnGet(ln, t, Evidence.LhPage()) != Evidence.LnGet(ln, l, Evidence.LhPage())) {
            return 0;
        }
        int sz = LsLineSize(sf, ln, l);
        if (LsCap(Evidence.LnGet(ln, t, Evidence.LhX1())) > (LsCap(Evidence.LnGet(ln, l, Evidence.LhX0())) + (sz / 4))) {
            return 0;
        }
        if ((LsAbs(LsCap(Evidence.LnGet(ln, l, Evidence.LhBy0())) - LsCap(Evidence.LnGet(ln, t, Evidence.LhBy0()))) * 3) > sz) {
            return 0;
        }
        if (LsGet(hc, t, LsKShape()) > 0) {
            return 1;
        }
        int w = LsFirstWord(wd, ln, t);
        if (w < 0) {
            return 0;
        }
        if (LsParse(wd, et, w, ws) == 1) {
            return 1;
        }
        return 0;
    }
    internal static int LsCollect(emon.Port.Cells wd, emon.Port.Cells ln, emon.Port.Cells et, emon.Port.Cells sf, emon.Port.Cells hc, emon.Port.Cells cd, emon.Port.Cells ws) {
        // One candidate row per line that starts with a marker, or with a bullet shape, in line order. Lines that are
        // headings, not upright, or already taken (a note, a caption) are left out; a line whose only word is the
        // marker has no item text and is left out.
        int n = Evidence.LnCount(ln);
        int l = 0;
        int c = 0;
        int w = 0;
        int tx = 0;
        int pt = 0;
        int rt = 0;
        int cls = 0;
        emon.Port.CellsDrop(cd, 0);
        while ((l < n) && (c < LsMaxcand)) {
            if (LsUpright(ln, l) && (Heading.HdLevel(hc, l) == 0) && (LsGet(hc, l, LsKFlags()) == 0)) {
                w = LsFirstWord(wd, ln, l);
                if ((w >= 0) && (LsSmall(wd, ln, sf, l) == 0)) {
                    cls = LsParse(wd, et, w, ws);
                    if ((cls == 2) && (LsLetterAfter(wd, ln, et, l, w) == 0)) {
                        cls = 0;
                    }
                    if (cls == 2) {
                        if (LsBulletBefore(wd, ln, et, sf, hc, l, ws) == 1) {
                            cls = 0;
                        } else {
                            LsParse(wd, et, w, ws);
                        }
                    }
                    if ((cls > 0) && ((emon.Port.CellsAt(ws, 4) < LsWl(wd, w)) || (LsSecondWord(wd, ln, l) >= 0))) {
                        tx = LsTextx(wd, ln, et, hc, l, w, cls, ws);
                        LsParse(wd, et, w, ws);
                        LsPushCand(cd, ln, l, emon.Port.CellsAt(ws, 0), emon.Port.CellsAt(ws, 1), emon.Port.CellsAt(ws, 2), emon.Port.CellsAt(ws, 3), emon.Port.CellsAt(ws, 5), cls, emon.Port.CellsAt(ws, 6), tx, -1);
                        c += 1;
                    }
                    // a marker alone on its line, its text on the line beside it
                    if ((cls > 0) && (emon.Port.CellsAt(ws, 4) == LsWl(wd, w)) && (LsSecondWord(wd, ln, l) < 0)) {
                        pt = LsPartner(wd, ln, sf, hc, l);
                        if (pt >= 0) {
                            LsParse(wd, et, w, ws);
                            rt = LsRtlSide(ln, l, pt);
                            tx = Evidence.LnGet(ln, pt, Evidence.LhX0());
                            if (rt == 1) {
                                tx = 10000000 - LsCap(Evidence.LnGet(ln, pt, Evidence.LhX1()));
                            }
                            LsPushCand(cd, ln, pt, emon.Port.CellsAt(ws, 0), emon.Port.CellsAt(ws, 1), emon.Port.CellsAt(ws, 2), emon.Port.CellsAt(ws, 3), emon.Port.CellsAt(ws, 5), cls, emon.Port.CellsAt(ws, 6), tx, l);
                            c += 1;
                        }
                    }
                    if ((cls == 0) && (LsGet(hc, l, LsKShape()) > 0)) {
                        tx = LsTextx(wd, ln, et, hc, l, w, 4, ws);
                        LsPushCand(cd, ln, l, LsScBullet(), 0, 0, 0, 0, 4, 0, tx, -1);
                        c += 1;
                    }
                }
            }
            l += 1;
        }
        return c;
    }
    internal static int LsCget(emon.Port.Cells cd, int i, int f) {
        return emon.Port.CellsAt(cd, (i * LsCd) + f);
    }
    internal static int LsCloseVal(int s, int v, int t, int u) {
        // 1 when two readings are of one scheme and their values differ by one to LS_NEAR.
        if ((s == 0) || (s != t)) {
            return 0;
        }
        int d = LsAbs(v - u);
        if ((d >= 1) && (d <= LsNear)) {
            return 1;
        }
        return 0;
    }
    internal static int LsConfirm(emon.Port.Cells cd, int nc, int i) {
        // Is candidate i corroborated by another near it: for a bullet, one of the same kind at the same indent on the
        // same or an adjacent page; for a number or a letter, one of the same scheme and punctuation at the same indent
        // whose value differs by one (or by a few: a list that skips). Answers the reading that is confirmed, 1 (the
        // candidate's first) or 2 (its second), 0 none.
        int cls = LsCget(cd, i, 8);
        int pg = LsCget(cd, i, 1);
        int x = LsCget(cd, i, 7);
        int j = LsMax(0, i - LsWin);
        int c1 = 0;
        int c2 = 0;
        while ((j < nc) && (j <= (i + LsWin))) {
            if ((j != i) && (LsAbs(LsCget(cd, j, 1) - pg) <= 1) && (LsAbs(LsCget(cd, j, 7) - x) <= LsXtol) && (LsCget(cd, j, 6) == LsCget(cd, i, 6))) {
                if ((cls == 1) || ((cls == 2) || (cls == 4))) {
                    if (cls == LsCget(cd, j, 8)) {
                        if ((cls == 4) || (LsCget(cd, j, 9) == LsCget(cd, i, 9))) {
                            c1 = 1;
                        }
                    }
                } else {
                    if ((1 == LsCloseVal(LsCget(cd, i, 2), LsCget(cd, i, 3), LsCget(cd, j, 2), LsCget(cd, j, 3))) || (1 == LsCloseVal(LsCget(cd, i, 2), LsCget(cd, i, 3), LsCget(cd, j, 4), LsCget(cd, j, 5)))) {
                        c1 = 1;
                    }
                    if ((1 == LsCloseVal(LsCget(cd, i, 4), LsCget(cd, i, 5), LsCget(cd, j, 2), LsCget(cd, j, 3))) || (1 == LsCloseVal(LsCget(cd, i, 4), LsCget(cd, i, 5), LsCget(cd, j, 4), LsCget(cd, j, 5)))) {
                        c2 = 1;
                    }
                }
            }
            j += 1;
        }
        if (c1 == 1) {
            return 1;
        }
        if (c2 == 1) {
            return 2;
        }
        return 0;
    }
    internal static int LsHangEvidence(emon.Port.Cells ln, emon.Port.Cells sf, emon.Port.Cells hc, int l, int textx) {
        // Does the line below l go on the item: not itself a marker line, starting at the item's text x, close below?
        int b = Style.StGet(sf, l, Style.SfkBelow());
        if (b < 0) {
            return 0;
        }
        if (!LsUpright(ln, b)) {
            return 0;
        }
        if (LsGet(hc, b, LsKFlags()) != 0) {
            return 0;
        }
        int sz = LsLineSize(sf, ln, l);
        int g = LsCap(Style.StGet(sf, l, Style.SfkGapBelow()));
        int bx = LsCap(Evidence.LnGet(ln, b, Evidence.LhX0()));
        int mx = LsCap(Evidence.LnGet(ln, l, Evidence.LhX0()));
        if ((g * 10) > (sz * 15)) {
            return 0;
        }
        if ((((bx - mx) * 100) >= (sz * 50)) && (LsAbs(bx - textx) <= (sz / 2))) {
            return 1;
        }
        return 0;
    }
    internal static int LsWalkFrom(emon.Port.Cells ln, emon.Port.Cells sf, emon.Port.Cells hc, int l) {
        // Mark the lines that GO ON the item line l: down the page while the next line is not a start, is upright, close below, and
        // sits at the item's text x. The same x and slop as the item's.
        int tx = LsGet(hc, l, LsKTextx());
        int tl = LsGet(hc, l, LsKTol());
        int cur = l;
        int steps = 0;
        int more = 1;
        while ((more == 1) && (steps < 200)) {
            int b = Style.StGet(sf, cur, Style.SfkBelow());
            more = 0;
            if ((b >= 0) && LsUpright(ln, b)) {
                if ((LsStart(hc, b) == 0) && ((LsGet(hc, b, LsKFlags()) & 2) == 0) && (Style.StGet(sf, cur, Style.SfkGapBelow()) <= (3 * tl)) && (Evidence.LnGet(ln, b, Evidence.LhX0()) >= (tx - tl)) && (Evidence.LnGet(ln, b, Evidence.LhX0()) <= (tx + tl))) {
                    LsPut(hc, b, LsKFlags(), LsFCont());
                    LsPut(hc, b, LsKTextx(), tx);
                    LsPut(hc, b, LsKTol(), tl);
                    cur = b;
                    more = 1;
                }
            }
            steps += 1;
        }
        return 0;
    }
    internal static int LsWalk(emon.Port.Cells ln, emon.Port.Cells sf, emon.Port.Cells hc) {
        // Mark the lines that GO ON an item: from each item line (`ls-walk-from`).
        int n = Evidence.LnCount(ln);
        int l = 0;
        while (l < n) {
            if ((LsGet(hc, l, LsKFlags()) & 1) == 1) {
                LsWalkFrom(ln, sf, hc, l);
            }
            l += 1;
        }
        return 0;
    }
    internal static int LsHangsUnder(emon.Port.Cells ln, emon.Port.Cells sf, emon.Port.Cells hc, int l) {
        // D1630 (smoke review B issue 12): 1 when line l sits where an item's text sits, under that item (an item line above it, or lines that go on it between, each at that x
        // and close under the last): a reference whose second line begins with an author's initial (`Y. Bengio`) is the item's continuation, not a new item.
        int cur = l;
        int steps = 0;
        int more = 1;
        int r = 0;
        while ((more == 1) && (steps < 60)) {
            int a = Style.StGet(sf, cur, Style.SfkAbove());
            more = 0;
            if ((a >= 0) && LsUpright(ln, a) && (LsCap(Style.StGet(sf, cur, Style.SfkGapAbove())) <= (3 * (LsLineSize(sf, ln, cur) / 2)))) {
                if ((LsGet(hc, a, LsKFlags()) & 1) != 0) {
                    int tx = LsGet(hc, a, LsKTextx());
                    int tl = LsGet(hc, a, LsKTol());
                    if (LsAbs(LsCap(Evidence.LnGet(ln, l, Evidence.LhX0())) - tx) <= tl) {
                        r = 1;
                    }
                } else {
                    if ((LsStart(hc, a) == 0) && (LsAbs(LsCap(Evidence.LnGet(ln, a, Evidence.LhX0())) - LsCap(Evidence.LnGet(ln, l, Evidence.LhX0()))) <= (LsLineSize(sf, ln, l) / 2))) {
                        cur = a;
                        more = 1;
                    }
                }
            }
            steps += 1;
        }
        return r;
    }
    internal static int LsInitialLike(emon.Port.Cells cd, int i) {
        // 1 when candidate i is a letter or a roman numeral and a full stop (`Z.`): it might be an author's initial, and a
        // hanging indent under it (a bibliography's) does not make it an item: only neighbours in a sequence do.
        if ((LsCget(cd, i, 8) == 3) && (LsCget(cd, i, 2) >= 3) && (LsCget(cd, i, 2) <= 7) && (LsCget(cd, i, 6) == 1)) {
            return 1;
        }
        return 0;
    }
    public static int LsAnalyze(emon.Port.Cells wd, emon.Port.Cells ln, emon.Port.Cells et, emon.Port.Cells sf, emon.Port.Cells pa, emon.Port.Cells hc, emon.Port.Cells cd, emon.Port.Cells pi, emon.Port.Cells ws, emon.Port.Cells tw) {
        // Find the lines that start an item and mark them (see the module's head). `cd`, `pi`, `ws` are scratch, `tw` the words of the tables' cells.
        // Answers the number of item lines found. The heading rows of `hc` must be there (`hd-analyze` ran); when
        // they are not nothing is done.
        if (LsOpen(hc) == 0) {
            return 0;
        }
        LsTaint(wd, ln, hc, tw);
        int i = 0;
        int found = 0;
        emon.Port.CellsDrop(ws, 0);
        while (i < 8) {
            emon.Port.CellsPush(ws, 0);
            i += 1;
        }
        if (LsPages(ln, pi) == 1) {
            LsShapes(ln, sf, pa, pi, hc);
        }
        int nc = LsCollect(wd, ln, et, sf, hc, cd, ws);
        i = 0;
        while (i < nc) {
            int l = LsCget(cd, i, 0);
            int cls = LsCget(cd, i, 8);
            int w = LsFirstWord(wd, ln, l);
            int conf = LsConfirm(cd, nc, i);
            int textx = LsCget(cd, i, 7);
            // a lone candidate needs a hanging continuation under it (a number or a letter, a bullet or a shape)
            if ((conf == 0) && (textx > 0) && (cls != 2) && (LsInitialLike(cd, i) == 0)) {
                if (LsHangEvidence(ln, sf, hc, l, textx) == 1) {
                    conf = 1;
                }
            }
            // an author's initial that begins the second line of a reference is the item's text (D1630)
            if ((conf > 0) && (LsInitialLike(cd, i) == 1) && (LsCget(cd, i, 3) >= 3)) {
                if (LsHangsUnder(ln, sf, hc, l) == 1) {
                    conf = 0;
                }
            }
            if (conf > 0) {
                int sch = LsPick(LsCget(cd, i, 2), LsCget(cd, i, 4), conf);
                int val = -1;
                int bch = -1;
                int partner = LsCget(cd, i, 10);
                int mlen = LsMlen(wd, et, w, ws);
                if (cls == 3) {
                    val = LsPick(LsCget(cd, i, 3), LsCget(cd, i, 5), conf);
                }
                if (cls == 4) {
                    int shape = LsGet(hc, l, LsKShape()) - 1;
                    int sx = Evidence.PaGet(pa, shape, Evidence.PfX0());
                    int sx1 = Evidence.PaGet(pa, shape, Evidence.PfX1());
                    LsWrapItem(wd, et, w, LsScBullet(), -1, 0, LsShapeChar(pa, shape));
                    if (LsGet(hc, l, LsKRtl()) == 1) {
                        if (sx1 > Evidence.LnGet(ln, l, Evidence.LhX1())) {
                            Evidence.LnSet(ln, l, Evidence.LhX1(), sx1);
                        }
                    } else {
                        if (sx < Evidence.LnGet(ln, l, Evidence.LhX0())) {
                            Evidence.LnSet(ln, l, Evidence.LhX0(), sx);
                        }
                    }
                } else if (partner >= 0) {
                    LsTakePartner(wd, et, ln, w, l, partner, sch, val);
                } else {
                    LsWrapItem(wd, et, w, sch, val, mlen, bch);
                }
                LsPut(hc, l, LsKFlags(), LsFItem());
                LsPut(hc, l, LsKTextx(), textx);
                LsPut(hc, l, LsKMarkx(), Evidence.LnGet(ln, l, Evidence.LhX0()));
                LsPut(hc, l, LsKTol(), LsLineSize(sf, ln, l) / 2);
                found += 1;
            }
            i += 1;
        }
        LsWalk(ln, sf, hc);
        return found;
    }
}
